// Mesma chave do painel admin.html: os produtos deste protótipo ficam neste navegador.
function lerProdutosDoPainel() {
  try {
    const produtos = JSON.parse(
      localStorage.getItem("levelup-admin-produtos") || "[]",
    );
    return Array.isArray(produtos) ? produtos : [];
  } catch {
    return [];
  }
}
function extrairIdYoutube(url) {
  const value = String(url || "").trim();
  const match = value.match(
    /(?:youtu\.be\/|youtube\.com\/(?:embed\/|shorts\/|watch\?v=))([A-Za-z0-9_-]{11})/,
  );
  return match ? match[1] : /^[A-Za-z0-9_-]{11}$/.test(value) ? value : "";
}
for (const produto of lerProdutosDoPainel()) {
  const preco = Number(produto.price);
  if (!produto.id || !produto.name || !Number.isFinite(preco) || preco <= 0)
    continue;
  const id = `admin-${String(produto.id).replace(/[^a-zA-Z0-9-]/g, "")}`;
  if (jogos.some((jogo) => jogo.id === id)) continue;
  const plataformas = String(produto.platform || "Não informada")
    .split(/[,;|]/)
    .map((item) => item.trim())
    .filter(Boolean);
  const imagem = String(
    produto.image ||
      "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 160 100'%3E%3Crect width='160' height='100' fill='%23121c2a'/%3E%3Ctext x='50%25' y='55%25' fill='%23ff682e' font-size='18' text-anchor='middle' font-family='Arial'%3ELEVELUP%3C/text%3E%3C/svg%3E",
  );
  jogos.push({
    id,
    nome: String(produto.name),
    categoria: String(produto.category || "Produto"),
    plataforma: plataformas,
    preco,
    precoTipo: "cadastrado",
    precoPlataforma: "Valor informado no painel administrativo",
    stock: Math.max(0, Number(produto.stock) || 0),
    imagem,
    resumo: String(
      produto.description || "Produto cadastrado pela equipe LEVELUP.",
    ),
    status: "Produto cadastrado pela equipe LEVELUP",
    ps5: "Consulte a descrição e a embalagem do produto.",
    xbox: "Consulte a descrição e a embalagem do produto.",
    pc: "Consulte a descrição e a embalagem do produto.",
    nintendo: "Consulte a descrição e a embalagem do produto.",
    trailer: extrairIdYoutube(produto.trailer),
    trailerNome: produto.trailer
      ? "Trailer informado no cadastro"
      : "Trailer não cadastrado",
    galeria: imagem ? [imagem] : [],
    fonte: String(produto.source || ""),
    destaque: false,
    preVenda: false,
  });
}

