const app = document.querySelector("#app");
let tema = "escuro";
const CHAT_THEME_KEY = "levelup-chat-theme";
function aplicarTemaDoAssistente(paleta) {
  document.body.classList.remove("tema-matrix", "tema-starwars", "tema-claro");
  tema = "escuro";
  if (paleta === "matrix" || paleta === "starwars") {
    document.body.classList.add(`tema-${paleta}`);
    try {
      localStorage.setItem(CHAT_THEME_KEY, paleta);
    } catch {
      // A paleta continua ativa nesta sessão mesmo sem armazenamento local.
    }
  } else {
    try {
      localStorage.removeItem(CHAT_THEME_KEY);
    } catch {
      // O tema padrão continua disponível nesta sessão.
    }
  }
}
try {
  const savedPalette = localStorage.getItem(CHAT_THEME_KEY);
  if (savedPalette === "matrix" || savedPalette === "starwars") {
    document.body.classList.add(`tema-${savedPalette}`);
  }
} catch {
  // A loja continua carregando caso o navegador bloqueie localStorage.
}
let carrinho = lerCarrinho();
let freightQuote = null; // Distância/custo só vivem nesta sessão; não guardamos o endereço.

function lerCarrinho() {
  try {
    return JSON.parse(localStorage.getItem("levelup-carrinho") || "[]");
  } catch {
    return [];
  }
}
function guardarCarrinho() {
  try {
    localStorage.setItem("levelup-carrinho", JSON.stringify(carrinho));
  } catch {
    /* carrinho continua nesta sessão */
  }
  const contador = document.querySelector(".botao-carrinho b");
  if (contador) contador.textContent = carrinho.reduce((n, i) => n + i.qtd, 0);
}
function dinheiro(valor) {
  return Number(valor).toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL",
  });
}
function textoPreco(jogo) {
  if (!Number.isFinite(jogo.preco) || jogo.preco <= 0)
    return "Preço oficial a anunciar";
  const rotulo =
    jogo.precoTipo === "cadastrado"
      ? "Preço cadastrado"
      : jogo.precoTipo === "estimado"
        ? "Estimativa LEVELUP"
        : jogo.precoAPartirDe
          ? "Preço oficial a partir de"
          : "Preço oficial consultado";
  return `${rotulo}: ${dinheiro(jogo.preco)}${jogo.precoPlataforma ? ` · ${jogo.precoPlataforma}` : ""}`;
}
function escapar(texto) {
  return String(texto).replace(
    /[&<>"']/g,
    (letra) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        letra
      ],
  );
}
function cabecalho() {
  return `<header class="topo"><a class="marca" href="#/">LEVEL<span>UP</span></a><nav><a href="#jogos">Jogos</a><a href="#destaques">Destaques</a><a href="#pre-venda">Pré-venda</a><a href="#consoles">Consolas</a></nav><div class="acoes-topo"><button class="botao botao-simples" data-acao="tema" type="button">☼ Tema</button><button class="botao botao-simples" type="button" onclick="window.location.href='login.html'">Acesso administrativo</button><button class="botao botao-carrinho" data-acao="abrir-carrinho">Carrinho <b>${carrinho.reduce((n, i) => n + i.qtd, 0)}</b></button></div></header>`;
}
function cartao(jogo) {
  const rotulo = jogo.preVenda
    ? "PRÉ-VENDA"
    : jogo.destaque
      ? "DESTAQUE"
      : jogo.plataforma.map(escapar).join(" · ");
  const lancamento =
    jogo.preVenda && jogo.lancamentoLabel
      ? `<small class="pre-venda-data">Lançamento: ${escapar(jogo.lancamentoLabel)}</small>`
      : "";
  const semEstoque = Number.isFinite(jogo.stock) && jogo.stock <= 0;
  const acao = jogo.preVenda
    ? `<a class="pequeno-botao" href="${escapar(jogo.preorderUrl || jogo.fonte.split(";")[0])}" target="_blank" rel="noopener">Pré-venda oficial ↗</a>`
    : `<button class="pequeno-botao" data-acao="adicionar" data-id="${jogo.id}" ${!jogo.preco || semEstoque ? "disabled" : ""}>${semEstoque ? "Sem estoque" : jogo.preco ? "Adicionar +" : "Preço a confirmar"}</button>`;
  return `<article class="card-jogo" data-id="${jogo.id}"><a class="capa" href="#/jogo/${jogo.id}"><img src="${escapar(jogo.imagem)}" alt="Imagem de ${escapar(jogo.nome)}" loading="lazy"><span class="selo">${rotulo}</span></a><div class="card-corpo"><p class="plataformas">${jogo.plataforma.map(escapar).join(" · ")}</p><h3><a href="#/jogo/${jogo.id}">${escapar(jogo.nome)}</a></h3><p class="genero">${escapar(jogo.categoria)}</p><div class="linha-card"><div><span class="preco-card">${escapar(textoPreco(jogo))}</span>${lancamento}</div>${acao}</div></div></article>`;
}
function cartaoConsola(c) {
  return `<article class="card-consola" data-console-id="${c.id}" data-console-category="${c.categoria}"><div class="foto-consola"><img src="${c.imagem}" alt="${escapar(c.nome)}" loading="lazy"></div><div class="corpo-consola"><p class="kicker">${escapar(c.categoria)}</p><h3>${escapar(c.nome)}</h3><p>${escapar(c.detalhe)}</p><span class="consulta-preco">Preço e disponibilidade: consultar loja</span><a class="botao botao-laranja" href="${escapar(c.url)}" target="_blank" rel="noopener">Ver opções de compra ↗</a></div></article>`;
}
function filtrarConsolas(categoria) {
  const grid = document.querySelector("#grade-consolas");
  if (!grid) return;
  document
    .querySelectorAll("[data-console-filter]")
    .forEach((b) =>
      b.classList.toggle("selecionado", b.dataset.consoleFilter === categoria),
    );
  grid.innerHTML = consoles
    .filter((c) => categoria === "Todas" || c.categoria === categoria)
    .map(cartaoConsola)
    .join("");
}

function paginaInicial() {
  const destaques = jogos.filter((j) => j.destaque);
  const catalogo = jogos;
  const reservas = jogos.filter((j) => j.preVenda);
  return `${cabecalho()}<main>
    <section class="hero hero-gta"><img class="hero-gta-img" src="${imagemBannerGta}" alt="Lucia e Jason em Vice City, de Grand Theft Auto VI" fetchpriority="high"><div class="hero-gta-copy"><p class="kicker">ROCKSTAR GAMES · GRANDE DESTAQUE</p><h1>GRAND THEFT<br><span>AUTO VI</span></h1><p>Vice City chama. Conheça o próximo capítulo de Grand Theft Auto.</p><p class="hero-gta-meta">PS5 · XBOX SERIES X|S · 19 NOVEMBRO 2026</p><div class="hero-gta-actions"><a class="botao botao-laranja" href="#/jogo/gta-vi">Ver GTA VI</a><a class="botao botao-simples" href="https://www.youtube.com/watch?v=VQRLujxTm3c" target="_blank" rel="noopener">Assistir trailer ↗</a></div></div></section>
    <section class="secao" id="destaques"><div class="titulo-secao"><div><p class="kicker">NO RADAR LEVELUP</p><h2>Jogos em destaque</h2></div><span>Veja trailers, galerias e disponibilidade por plataforma.</span></div><div class="grade destaques">${destaques.map(cartao).join("")}</div></section>
    <section class="secao" id="pre-venda"><div class="titulo-secao"><div><p class="kicker">GARANTA SUA CÓPIA</p><h2>Pré-venda</h2></div><span>Datas e disponibilidade conforme anúncio oficial.</span></div><div class="grade pre-venda">${reservas.map(cartao).join("")}</div></section>
    <section class="secao" id="consoles"><div class="titulo-secao"><div><p class="kicker">HARDWARE PARA JOGAR</p><h2>Comprar consolas</h2></div><span>Escolha a plataforma e consulte preço e stock na loja oficial.</span></div><div class="filtros filtros-consolas">${["Todas", "PlayStation", "Xbox", "Nintendo"].map((p) => `<button class="filtro ${p === "Todas" ? "selecionado" : ""}" data-console-filter="${p}">${p}</button>`).join("")}</div><div class="grade grade-consoles" id="grade-consoles">${consoles.map(cartaoConsola).join("")}</div><p class="nota-console">Os preços e a disponibilidade variam por região, versão e revendedor. A LEVELUP não processa pagamentos de consolas; os botões abrem as páginas oficiais para consulta e compra.</p></section>
    <section class="secao" id="jogos"><div class="titulo-secao"><div><p class="kicker">CATÁLOGO MULTIPLATAFORMA</p><h2>Todos os jogos</h2></div><label class="busca"><span>⌕</span><input id="pesquisar" type="search" placeholder="Pesquisar jogo" aria-label="Pesquisar jogos"></label></div><div class="filtros">${["Todos", "PS5", "Xbox", "Nintendo Switch", "PC"].map((p) => `<button class="filtro ${p === "Todos" ? "selecionado" : ""}" data-filtro="${p}">${p}</button>`).join("")}</div><div class="grade catalogo" id="catalogo">${catalogo.map(cartao).join("")}</div></section>
    <section class="secao carrinho-demo"><div><p class="kicker">SOMA EM TEMPO REAL</p><h2>Carrinho dinâmico</h2><p>Use os botões para somar valores ao carrinho de demonstração.</p></div><div class="somador"><div class="botoes-soma">${[10, 20, 30].map((v) => `<button class="botao" data-acao="somar" data-valor="${v}">+ ${dinheiro(v)}</button>`).join("")}</div><strong id="total-rapido">Total rápido: ${dinheiro(carrinho.filter((i) => i.tipo === "rapido").reduce((s, i) => s + i.preco * i.qtd, 0))}</strong><button class="texto-botao" data-acao="zerar-rapido">Zerar valores rápidos</button></div></section>
    <section class="secao futuro chat-cta"><div><p class="kicker">PROCURA UMA AVENTURA?</p><h2>O assistente ajuda a encontrar o jogo.</h2><p>Envie uma imagem de capa ou pergunte sobre plataformas cadastradas.</p></div><button class="botao botao-laranja" data-acao="abrir-assistente">Falar com o LEVELUP Assistente</button></section>
  </main>${rodape()}${gaveta()}`;
}
function disponibilidade(j) {
  return `<div class="requisitos"><article><h3>PlayStation 5</h3><p>${escapar(j.ps5)}</p></article><article><h3>Xbox Series X|S</h3><p>${escapar(j.xbox)}</p></article><article><h3>PC · requisitos mínimos</h3><p>${escapar(j.pc)}</p></article></div>${j.nintendo ? `<p class="nota-console"><strong>Nintendo Switch 2:</strong> ${escapar(j.nintendo)}</p>` : ""}<p class="nota-console">Consolas usam hardware fixo. Os fabricantes não publicam uma lista de requisitos mínimos de PC para PS5 ou Xbox; estas fichas indicam suporte e compatibilidade.</p>`;
}
function paginaJogo(j) {
  const semEstoque = Number.isFinite(j.stock) && j.stock <= 0;
  const sources = String(j.fonte || "")
    .split(";")
    .map((url) => url.trim())
    .filter(Boolean);
  const gallery = j.galeria
    .map((src, i) => {
      const url =
        src === "data-gta-1"
          ? imagensGta[0]
          : src === "data-gta-2"
            ? imagensGta[1]
            : src === "__OCARINA_SCREEN_1__"
              ? imagensOcarina[1]
              : src === "__OCARINA_SCREEN_2__"
                ? imagensOcarina[2]
                : src === "data-tomb-1"
                  ? imagensTombRaider[1]
                  : src === "data-tomb-2"
                    ? imagensTombRaider[2]
                    : src;
      return `<a class="imagem-galeria" href="${escapar(url)}" target="_blank" rel="noopener"><img src="${escapar(url)}" alt="Screenshot ${i + 1} de ${escapar(j.nome)}" loading="lazy"></a>`;
    })
    .join("");
  const status = j.preVenda
    ? `<span class="estado pre">Pré-venda aberta · lançamento previsto para ${escapar(j.lancamentoLabel || "data a confirmar")}</span>`
    : `<span class="estado">${j.status || "Ficha informativa"}</span>`;
  return `${cabecalho()}<main class="pagina-jogo"><a class="voltar" href="#jogos">← Voltar à loja</a><section class="jogo-hero"><img src="${escapar(j.imagem)}" alt="Imagem de ${escapar(j.nome)}"><div class="jogo-capa-sombra"></div><div class="jogo-titulo">${status}<p class="kicker">${j.plataforma.join(" · ")}</p><h1>${escapar(j.nome)}</h1><p>${escapar(j.resumo)}</p><div class="botoes-jogo">${j.preco > 0 ? `<span class="preco-detalhe">${escapar(textoPreco(j))}</span><button class="botao botao-laranja" data-acao="adicionar" data-id="${j.id}" ${semEstoque ? "disabled" : ""}>${semEstoque ? "Sem estoque" : `${j.preVenda ? "Reservar" : "Adicionar ao carrinho"} · ${dinheiro(j.preco)}`}</button>` : ""}${j.preVenda ? `<a class="botao botao-simples" href="${escapar(j.preorderUrl || j.fonte.split(";")[0])}" target="_blank" rel="noopener">Pré-venda oficial ↗</a>` : ""}${sources.length ? `<a class="botao botao-simples" href="${escapar(sources[0])}" target="_blank" rel="noopener">Fonte / página do produto ↗</a>` : ""}</div></div></section>
    ${["spider-man-2", "red-dead-2"].includes(j.id) ? `<section class="secao"><div class="titulo-secao"><div><p class="kicker">ORGANIZE SUA JORNADA</p><h2>Lista de tarefas</h2></div></div><div class="task-form"><input id="task-input" type="text" maxlength="120" placeholder="Escreva uma tarefa para este jogo" aria-label="Nova tarefa"><button class="botao botao-laranja" data-acao="adicionar-tarefa">Adicionar tarefa</button></div><ul id="task-list" class="task-list"></ul></section>` : ""}
    <section class="secao"><div class="titulo-secao"><div><p class="kicker">COMPATIBILIDADE</p><h2>Plataformas e requisitos</h2></div></div>${disponibilidade(j)}</section>
    <section class="secao"><div class="titulo-secao"><div><p class="kicker">ASSISTA</p><h2>${escapar(j.trailerNome)}</h2></div></div>${j.trailer ? `<div class="trailer"><iframe src="https://www.youtube-nocookie.com/embed/${j.trailer}?rel=0" title="${escapar(j.trailerNome)} — ${escapar(j.nome)}" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><a class="link-fonte" href="https://www.youtube.com/watch?v=${j.trailer}" target="_blank" rel="noopener">Abrir trailer no YouTube ↗</a>` : `<p class="nota-console">${escapar(j.trailerNome || "Trailer não cadastrado")}</p>`}</section>
    <section class="secao"><div class="titulo-secao"><div><p class="kicker">IMAGENS OFICIAIS</p><h2>Galeria do jogo</h2></div></div><div class="galeria">${gallery}</div></section><section class="secao"><p class="kicker">CONSULTA E CONFIRMAÇÃO</p><h2>Fontes oficiais</h2><div class="fontes">${sources.length ? sources.map((url) => `<a href="${escapar(url)}" target="_blank" rel="noopener">Abrir fonte ↗</a>`).join("") : "<span>Fonte não informada no cadastro.</span>"}</div></section><p class="aviso-factual">As datas, plataformas e especificações refletem as fontes oficiais disponíveis nesta página. “Não anunciado” não significa confirmação futura.</p></main>${rodape()}${gaveta()}`;
}
function rodape() {
  return `<footer class="rodape"><a class="marca" href="#/">LEVEL<span>UP</span></a><p>Projeto demonstrativo. Marcas e imagens pertencem aos respetivos titulares. Preços de lojas oficiais consultados em 10/11/2026; valores estimados estão identificados. Preços podem mudar; o carrinho não processa pagamentos nem encomendas.</p></footer>`;
}
function gaveta() {
  return `<div class="fundo-gaveta" data-acao="fechar-carrinho" hidden></div><aside class="gaveta" id="gaveta" aria-label="Carrinho de demonstração" hidden><div class="cabecalho-gaveta"><h2>Seu carrinho</h2><button class="fechar" data-acao="fechar-carrinho" aria-label="Fechar carrinho">×</button></div><p class="aviso-carrinho">Demonstração: nenhuma compra ou pagamento será processado.</p><div id="itens-carrinho"></div><div class="resumo-carrinho"><p>Subtotal <b id="subtotal-carrinho">${dinheiro(0)}</b></p><p id="frete-carrinho">Frete <b>${freightQuote ? dinheiro(freightQuote.cost) : "a calcular"}</b></p><p>Total <strong id="total-carrinho">${dinheiro(0)}</strong></p><button class="botao botao-laranja largura" data-acao="checkout">Continuar (demonstração)</button><button class="texto-botao" data-acao="limpar">Esvaziar carrinho</button></div><div class="soma-gaveta">${[10, 20, 30].map((v) => `<button class="botao" data-acao="somar" data-valor="${v}">+${dinheiro(v)}</button>`).join("")}</div></aside>`;
}
function mostrarCarrinho() {
  const drawer = document.querySelector("#gaveta");
  const bg = document.querySelector(".fundo-gaveta");
  if (!drawer || !bg) return;
  drawer.hidden = false;
  bg.hidden = false;
  document.body.classList.add("trava");
  desenharCarrinho();
}
function fecharCarrinho() {
  document.querySelector("#gaveta")?.setAttribute("hidden", "");
  document.querySelector(".fundo-gaveta")?.setAttribute("hidden", "");
  document.body.classList.remove("trava");
}
function desenharCarrinho() {
  const area = document.querySelector("#itens-carrinho");
  if (!area) return;
  if (!carrinho.length)
    area.innerHTML = '<p class="vazio">Seu carrinho está vazio.</p>';
  else
    area.innerHTML = carrinho
      .map(
        (item) =>
          `<article class="item-carrinho"><img src="${item.imagem || ""}" alt=""><div><b>${escapeHTML(item.nome)}</b><small>${dinheiro(item.preco)}${item.precoTipo === "estimado" ? " · estimativa LEVELUP" : ""} · qtd. ${item.qtd}</small><div class="quantidade"><button data-acao="qtd" data-id="${item.id}" data-delta="-1">−</button><button data-acao="qtd" data-id="${item.id}" data-delta="1">+</button><button data-acao="remover" data-id="${item.id}">Remover</button></div></div></article>`,
      )
      .join("");
  const subtotalValue = carrinho.reduce((s, i) => s + i.preco * i.qtd, 0);
  const freightValue = freightQuote?.cost || 0;
  const subtotal = document.querySelector("#subtotal-carrinho");
  const freightNode = document.querySelector("#frete-carrinho");
  const totalNode = document.querySelector("#total-carrinho");
  if (subtotal) subtotal.textContent = dinheiro(subtotalValue);
  if (freightNode)
    freightNode.innerHTML = `Frete <b>${freightQuote ? dinheiro(freightValue) : "a calcular"}</b>`;
  if (totalNode) totalNode.textContent = dinheiro(subtotalValue + freightValue);
}
function escapeHTML(s) {
  return escapar(s);
}
function adicionar(id) {
  const j = jogos.find((x) => x.id === id);
  if (!j || !j.preco) return;
  const line = carrinho.find((x) => x.id === id);
  if (
    Number.isFinite(j.stock) &&
    (j.stock <= 0 || (line && line.qtd >= j.stock))
  ) {
    alert("Não há estoque disponível para adicionar mais unidades.");
    return;
  }
  if (line) line.qtd++;
  else
    carrinho.push({
      id: j.id,
      nome: j.nome,
      preco: j.preco,
      precoTipo: j.precoTipo,
      precoPlataforma: j.precoPlataforma,
      stock: j.stock,
      qtd: 1,
      imagem: j.imagem,
      tipo: "jogo",
    });
  guardarCarrinho();
  desenharCarrinho();
  const count = document.querySelector(".botao-carrinho b");
  if (count) count.textContent = carrinho.reduce((n, i) => n + i.qtd, 0);
}
function somar(valor) {
  const id = `rapido-${valor}`;
  const line = carrinho.find((x) => x.id === id);
  if (line) line.qtd++;
  else
    carrinho.push({
      id,
      nome: `Valor rápido ${dinheiro(valor)}`,
      preco: valor,
      qtd: 1,
      tipo: "rapido",
    });
  guardarCarrinho();
  desenharCarrinho();
  const rapid = document.querySelector("#total-rapido");
  if (rapid)
    rapid.textContent = `Total rápido: ${dinheiro(carrinho.filter((i) => i.tipo === "rapido").reduce((s, i) => s + i.preco * i.qtd, 0))}`;
}
function desenhar() {
  const route = location.hash.slice(1);
  const match = route.match(/^\/jogo\/([a-z0-9-]+)$/);
  const jogo = match && jogos.find((j) => j.id === match[1]);
  app.innerHTML = jogo ? paginaJogo(jogo) : paginaInicial();
  document.body.classList.toggle("tema-claro", tema === "claro");
  const contador = document.querySelector(".botao-carrinho b");
  if (contador) contador.textContent = carrinho.reduce((n, i) => n + i.qtd, 0);
}
window.addEventListener("hashchange", () => {
  if (location.hash.startsWith("#/")) desenhar();
});
document.addEventListener("click", (event) => {
  const anchor = event.target.closest('a[href^="#"]');
  if (
    anchor &&
    !anchor.getAttribute("href").startsWith("#/") &&
    location.hash.startsWith("#/jogo/")
  ) {
    event.preventDefault();
    const target = anchor.getAttribute("href").slice(1);
    location.hash = "#/";
    setTimeout(
      () =>
        document.getElementById(target)?.scrollIntoView({ behavior: "smooth" }),
      80,
    );
    return;
  }
  const action = event.target.closest("[data-acao]");
  if (action) {
    const what = action.dataset.acao;
    if (what === "tema") {
      if (
        document.body.classList.contains("tema-matrix") ||
        document.body.classList.contains("tema-starwars")
      ) {
        aplicarTemaDoAssistente("normal");
        document.body.classList.remove("tema-claro");
        tema = "escuro";
      } else {
        tema = tema === "claro" ? "escuro" : "claro";
        document.body.classList.toggle("tema-claro", tema === "claro");
      }
    }
    if (what === "abrir-carrinho") mostrarCarrinho();
    if (what === "fechar-carrinho") fecharCarrinho();
    if (what === "adicionar") {
      adicionar(action.dataset.id);
      mostrarCarrinho();
    }
    if (what === "comprar-chat") {
      adicionar(action.dataset.id);
      mostrarCarrinho();
    }
    if (what === "somar") {
      somar(Number(action.dataset.valor));
    }
    if (what === "limpar") {
      carrinho = [];
      guardarCarrinho();
      desenharCarrinho();
    }
    if (what === "zerar-rapido") {
      carrinho = carrinho.filter((i) => i.tipo !== "rapido");
      guardarCarrinho();
      desenhar();
    }
    if (what === "remover") {
      carrinho = carrinho.filter((i) => i.id !== action.dataset.id);
      guardarCarrinho();
      desenharCarrinho();
    }
    if (what === "qtd") {
      const item = carrinho.find((i) => i.id === action.dataset.id);
      const delta = Number(action.dataset.delta);
      if (
        item &&
        delta > 0 &&
        Number.isFinite(item.stock) &&
        item.qtd >= item.stock
      ) {
        alert("Não há estoque disponível para adicionar mais unidades.");
        return;
      }
      if (item) item.qtd += delta;
      carrinho = carrinho.filter((i) => i.qtd > 0);
      guardarCarrinho();
      desenharCarrinho();
    }
    if (what === "checkout")
      alert(
        "Esta é uma demonstração. Nenhum pedido ou pagamento será realizado.",
      );
    if (what === "adicionar-tarefa") {
      const input = document.querySelector("#task-input");
      const value = input?.value.trim();
      if (!value) {
        input?.classList.add("input-erro");
        input?.setAttribute("aria-invalid", "true");
        input?.focus();
        return;
      }
      const li = document.createElement("li");
      const text = document.createElement("span");
      text.textContent = value;
      const remove = document.createElement("button");
      remove.type = "button";
      remove.className = "remover-tarefa";
      remove.textContent = "Remover";
      remove.setAttribute("data-acao", "remover-tarefa");
      li.append(text, remove);
      document.querySelector("#task-list")?.append(li);
      input.value = "";
      input.classList.remove("input-erro");
      input.removeAttribute("aria-invalid");
    }
    if (what === "remover-tarefa") action.closest("li")?.remove();
  }
  const filter = event.target.closest("[data-filtro]");
  if (filter) {
    document
      .querySelectorAll("[data-filtro]")
      .forEach((b) => b.classList.toggle("selecionado", b === filter));
    filtrar(filter.dataset.filtro);
  }
  const consoleFilter = event.target.closest("[data-console-filter]");
  if (consoleFilter) filtrarConsolas(consoleFilter.dataset.consoleFilter);
});
document.addEventListener("input", (event) => {
  if (event.target.id === "pesquisar")
    filtrar(
      document.querySelector(".filtro.selecionado")?.dataset.filtro || "Todos",
    );
  if (event.target.id === "task-input" && event.target.value.trim()) {
    event.target.classList.remove("input-erro");
    event.target.removeAttribute("aria-invalid");
  }
});
function filtrar(platform) {
  const term = (
    document.querySelector("#pesquisar")?.value || ""
  ).toLocaleLowerCase("pt-BR");
  document.querySelectorAll("#catalogo .card-jogo").forEach((card) => {
    const j = jogos.find((x) => x.id === card.dataset.id);
  });
  const grid = document.querySelector("#catalogo");
  if (!grid) return;
  grid.innerHTML = jogos
    .filter((j) => !j.preVenda)
    .filter(
      (j) =>
        (platform === "Todos" ||
          j.plataforma.some((item) => item.includes(platform))) &&
        j.nome.toLocaleLowerCase("pt-BR").includes(term),
    )
    .map(cartao)
    .join("");
}
document.addEventListener("keydown", (event) => {
  if (event.key === "Escape") fecharCarrinho();
});
desenhar();

// LEVELUP Assistente: mensagens seguras por DOM e reconhecimento local com Teachable Machine.
const CHAT_MODEL_DIR = "./my_model/";
const CHAT_MAX_IMAGE_BYTES = 5 * 1024 * 1024;
const CHAT_MIN_CONFIDENCE = 0.65;
const CHAT_CLASS_TO_GAME = {
  "god of war": "god-of-war-laufey",
  "god of war laufey": "god-of-war-laufey",
  "spider man 2": "spider-man-2",
  "marvel s spider man 2": "spider-man-2",
  "gta 6": "gta-vi",
  "gta vi": "gta-vi",
  "grand theft auto 6": "gta-vi",
  "spider man": "spider-man-2",
  "marvels spider man 2": "spider-man-2",
  "red dead redemption": "red-dead-2",
  "red dead redemption 2": "red-dead-2",
  gta: "gta-vi",
  "grand theft auto": "gta-vi",
  "grand theft auto vi": "gta-vi",
  "ocarina of time": "ocarina-of-time-remake",
  "zelda ocarina of time": "ocarina-of-time-remake",
  "call of duty modern warfare 4": "modern-warfare-4",
  "modern warfare 4": "modern-warfare-4",
  "marvel s wolverine": "wolverine",
  "marvels wolverine": "wolverine",
  "marvel wolverine": "wolverine",
  wolverine: "wolverine",
  "tomb raider legacy of atlantis": "tomb-raider-legacy-atlantis",
  "tomb raider": "tomb-raider-legacy-atlantis",
  "forza horizon 5": "forza-horizon-5",
  "cyberpunk 2077": "cyberpunk-2077",
  "ea sports fc 27": "ea-fc-27",
  "fc 27": "ea-fc-27",
  "fifa 27": "ea-fc-27",
  "resident evil requiem": "resident-evil-requiem",
  requiem: "resident-evil-requiem",
};
let chatModelPromise = null;
let chatSelectedFile = null;
let chatPreviewUrl = "";
let chatAnalyzing = false;
let chatLastGame = null;

function chatNormalize(value) {
  return String(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}
function chatElement(id) {
  return document.getElementById(id);
}
function chatScrollToBottom() {
  const log = chatElement("chat-messages");
  if (log) log.scrollTop = log.scrollHeight;
}
function chatAddMessage(kind, text, fileName = "") {
  const log = chatElement("chat-messages");
  if (!log) return null;
  const bubble = document.createElement("div");
  bubble.className = `chat-message chat-${kind}`;
  const paragraph = document.createElement("p");
  paragraph.textContent = text;
  bubble.append(paragraph);
  if (fileName) {
    const caption = document.createElement("small");
    caption.textContent = `Imagem enviada: ${fileName}`;
    bubble.append(caption);
  }
  log.append(bubble);
  chatScrollToBottom();
  return bubble;
}
function chatSetStatus(text = "") {
  const status = chatElement("chat-status");
  const label = chatElement("chat-status-text");
  if (!status || !label) return;
  label.textContent = text;
  status.hidden = !text;
}
function chatSetBusy(busy) {
  chatAnalyzing = busy;
  const send = document.querySelector('#chat-form button[type="submit"]');
  const input = chatElement("chat-text");
  const choose = chatElement("chat-select-image");
  if (send) send.disabled = busy;
  if (input) input.disabled = busy;
  if (choose) choose.disabled = busy;
}
function chatClearPreview(revoke = true) {
  if (revoke && chatPreviewUrl) URL.revokeObjectURL(chatPreviewUrl);
  chatPreviewUrl = "";
  chatSelectedFile = null;
  const preview = chatElement("chat-preview");
  const image = chatElement("chat-preview-image");
  const name = chatElement("chat-preview-name");
  const input = chatElement("chat-file");
  if (image) image.removeAttribute("src");
  if (name) name.textContent = "";
  if (preview) preview.hidden = true;
  if (input) input.value = "";
}
function chatLoadScript(src, globalName) {
  if (window[globalName]) return Promise.resolve();
  return new Promise((resolve, reject) => {
    const existing = [...document.scripts].find((script) => script.src === src);
    if (existing) {
      existing.addEventListener("load", resolve, { once: true });
      existing.addEventListener(
        "error",
        () =>
          reject(
            new Error(
              "Não foi possível carregar a biblioteca de reconhecimento.",
            ),
          ),
        { once: true },
      );
      if (window[globalName]) resolve();
      return;
    }
    const script = document.createElement("script");
    script.src = src;
    script.async = true;
    script.onload = resolve;
    script.onerror = () =>
      reject(
        new Error(
          "Falha ao carregar a biblioteca Teachable Machine. Verifique a ligação à internet e tente novamente.",
        ),
      );
    document.head.append(script);
  });
}
async function chatLoadModel() {
  if (!chatModelPromise) {
    chatModelPromise = (async () => {
      chatSetStatus("Carregando o modelo de reconhecimento…");
      if (location.protocol === "file:") {
        throw new Error(
          "Abra o site com Live Server no VS Code. O navegador não carrega model.json diretamente por file://.",
        );
      }
      const modelUrl = `${CHAT_MODEL_DIR}model.json`;
      const metadataUrl = `${CHAT_MODEL_DIR}metadata.json`;
      let modelResponse;
      let metadataResponse;
      try {
        [modelResponse, metadataResponse] = await Promise.all([
          fetch(modelUrl, { cache: "no-store" }),
          fetch(metadataUrl, { cache: "no-store" }),
        ]);
      } catch {
        throw new Error(
          "Não consegui aceder a ./my_model/. Coloque model.json, metadata.json e weights.bin nessa pasta, ao lado de index.html.",
        );
      }
      if (!modelResponse.ok || !metadataResponse.ok) {
        throw new Error(
          "Modelo Teachable Machine não encontrado. Confira ./my_model/model.json, metadata.json e weights.bin.",
        );
      }
      try {
        await modelResponse.json();
        await metadataResponse.json();
      } catch {
        throw new Error(
          "Os arquivos model.json ou metadata.json estão inválidos. Exporte novamente o modelo Teachable Machine.",
        );
      }
      await chatLoadScript(
        "https://cdn.jsdelivr.net/npm/@tensorflow/tfjs@latest/dist/tf.min.js",
        "tf",
      );
      await chatLoadScript(
        "https://cdn.jsdelivr.net/npm/@teachablemachine/image@latest/dist/teachablemachine-image.min.js",
        "tmImage",
      );
      if (!window.tmImage || typeof window.tmImage.load !== "function") {
        throw new Error(
          "A biblioteca de imagens do Teachable Machine não ficou disponível.",
        );
      }
      try {
        return await window.tmImage.load(modelUrl, metadataUrl);
      } catch {
        throw new Error(
          "Falha ao carregar o modelo ou os pesos. Confirme se weights.bin está junto dos outros arquivos em ./my_model/.",
        );
      }
    })().catch((error) => {
      chatModelPromise = null;
      throw error;
    });
  }
  return chatModelPromise;
}
function chatFindGameForLabel(label) {
  const normalized = chatNormalize(label);
  const exactId = CHAT_CLASS_TO_GAME[normalized];
  if (exactId) return jogos.find((game) => game.id === exactId) || null;
  if (
    normalized.startsWith("god of war ") &&
    normalized !== "god of war laufey"
  )
    return null;
  const alias = Object.keys(CHAT_CLASS_TO_GAME).find((key) =>
    normalized.includes(key),
  );
  if (alias)
    return jogos.find((game) => game.id === CHAT_CLASS_TO_GAME[alias]) || null;
  return null;
}
function chatShowGameCard(game) {
  const card = document.createElement("article");
  card.className = "chat-game-card";
  const image = document.createElement("img");
  image.src = game.imagem;
  image.alt = `Imagem de ${game.nome}`;
  image.loading = "lazy";
  const info = document.createElement("div");
  info.className = "chat-game-info";
  const title = document.createElement("strong");
  title.textContent = game.nome;
  const platforms = document.createElement("small");
  platforms.textContent = `Plataformas: ${game.plataforma.join(" · ")}`;
  info.append(title, platforms);
  const price = document.createElement("small");
  price.textContent = textoPreco(game);
  info.append(price);
  const buy = document.createElement("button");
  buy.type = "button";
  buy.className = "botao botao-laranja chat-game-link";
  buy.dataset.acao = "comprar-chat";
  buy.dataset.id = game.id;
  buy.disabled = !(Number.isFinite(game.preco) && game.preco > 0);
  buy.textContent = "Comprar · abrir carrinho";
  card.append(image, info, buy);
  const log = chatElement("chat-messages");
  if (log) log.append(card);
  chatScrollToBottom();
}
function chatAnswerText(text) {
  const query = chatNormalize(text);
  if (/\bmatrix\b/.test(query)) {
    aplicarTemaDoAssistente("matrix");
    chatAddMessage(
      "bot",
      "Tema Matrix ativado: fundo preto e verde fluorescente. Para trocar, digite starwars; para voltar ao tema claro/escuro normal, use o botão Tema.",
    );
    return;
  }
  if (/\bstar\s*wars\b/.test(query)) {
    aplicarTemaDoAssistente("starwars");
    chatAddMessage(
      "bot",
      "Tema Star Wars ativado: fundo preto e vermelho. Para trocar, digite matrix; para voltar ao tema claro/escuro normal, use o botão Tema.",
    );
    return;
  }
  if (/\b(frete|entrega)\b/.test(query)) {
    chatAddMessage(
      "bot",
      "Vamos calcular o frete desde Guaratinguetá. Informe o destino, abra a rota de carro no Google Maps e copie a distância em km para o formulário. O endereço só vai ao Google Maps se você abrir o link.",
    );
    const shipping = chatElement("chat-shipping");
    if (shipping) {
      shipping.open = true;
      shipping.scrollIntoView({ behavior: "smooth", block: "nearest" });
    }
    return;
  }
  const mentioned =
    jogos.find((game) => query.includes(chatNormalize(game.nome))) || null;
  const hasOtherGodOfWarTitle =
    /god of war (ragnarok|2018|ascension|iii|ii)\b/.test(query);
  const alias = Object.keys(CHAT_CLASS_TO_GAME).find(
    (key) =>
      query.includes(key) && !(key === "god of war" && hasOtherGodOfWarTitle),
  );
  const game =
    mentioned ||
    (alias
      ? jogos.find((item) => item.id === CHAT_CLASS_TO_GAME[alias])
      : null) ||
    chatLastGame;
  if (
    /\b(oi|ola|bom dia|boa tarde|boa noite|hello|ola tudo bem)\b/.test(query)
  ) {
    chatAddMessage(
      "bot",
      "Olá! Bem-vindo à LEVELUP! Posso ajudar você a encontrar seu próximo jogo.",
    );
    return;
  }
  if (/\b(preco|valor|quanto custa)\b/.test(query)) {
    if (game && Number.isFinite(game.preco) && game.preco > 0) {
      chatAddMessage(
        "bot",
        `${textoPreco(game)} para ${game.nome}. O carrinho é demonstrativo e não processa compras.`,
      );
    } else if (game) {
      chatAddMessage(
        "bot",
        `Ainda não há um preço numérico cadastrado para ${game.nome}.`,
      );
    } else {
      chatAddMessage(
        "bot",
        "Qual jogo você quer consultar? Só informo preços que estejam cadastrados no catálogo demonstrativo.",
      );
    }
    return;
  }
  const platform = /\b(ps5|playstation)\b/.test(query)
    ? "ps5"
    : /\b(xbox)\b/.test(query)
      ? "xbox"
      : /\b(pc|computador)\b/.test(query)
        ? "pc"
        : /\b(nintendo|switch)\b/.test(query)
          ? "nintendo"
          : "";
  if (platform) {
    if (game)
      chatAddMessage(
        "bot",
        `${game.nome}: ${game[platform] || "Não há informação cadastrada para essa plataforma."}`,
      );
    else
      chatAddMessage(
        "bot",
        "Diga o nome do jogo ou envie uma imagem para eu consultar a plataforma correspondente.",
      );
    return;
  }
  if (game) {
    chatLastGame = game;
    chatAddMessage(
      "bot",
      `${game.nome}: ${game.status || `plataformas cadastradas: ${game.plataforma.join(" · ")}`}.`,
    );
    chatShowGameCard(game);
    return;
  }
  chatAddMessage(
    "bot",
    "Posso identificar capas de jogos com o modelo de imagem, consultar plataformas de um jogo do catálogo ou abrir a ficha dele. Qual jogo você procura?",
  );
}
async function chatAnalyzeImage(file, objectUrl) {
  if (chatAnalyzing) return;
  chatSetBusy(true);
  chatSetStatus("Analisando a imagem…");
  try {
    const image = new Image();
    image.src = objectUrl;
    try {
      await image.decode();
    } catch {
      throw new Error(
        "A imagem não pôde ser aberta. Tente um arquivo PNG, JPG ou WebP válido.",
      );
    }
    const model = await chatLoadModel();
    chatSetStatus("Comparando a imagem com as classes do modelo…");
    const predictions = await model.predict(image);
    const best = predictions.reduce(
      (top, item) => (item.probability > top.probability ? item : top),
      predictions[0],
    );
    if (!best || !best.className)
      throw new Error("O modelo não retornou nenhuma classe reconhecível.");
    if (best.probability < CHAT_MIN_CONFIDENCE) {
      chatAddMessage(
        "bot",
        "Não consegui identificar o jogo com confiança suficiente. Tente uma imagem mais nítida, mostrando a capa ou uma cena do jogo.",
      );
      return;
    }
    const game = chatFindGameForLabel(best.className);
    if (!game) {
      chatAddMessage(
        "bot",
        `Reconheci a classe “${best.className}”, mas ainda não encontrei esse jogo no catálogo da LEVELUP.`,
      );
      return;
    }
    chatLastGame = game;
    const className = chatNormalize(best.className);
    const isGodOfWarFamily =
      className === "god of war" && game.id === "god-of-war-laufey";
    chatAddMessage(
      "bot",
      isGodOfWarFamily
        ? `Identifiquei uma imagem da série God of War. O jogo correspondente cadastrado na loja é ${game.nome}! 🎮`
        : `Identifiquei que a imagem parece ser do jogo ${game.nome}! 🎮`,
    );
    chatShowGameCard(game);
  } finally {
    if (objectUrl) URL.revokeObjectURL(objectUrl);
    chatSetStatus("");
    chatSetBusy(false);
  }
}
function chatOpen() {
  const panel = chatElement("chat-panel");
  const toggle = chatElement("chat-toggle");
  if (!panel || !toggle) return;
  panel.hidden = false;
  toggle.setAttribute("aria-expanded", "true");
  chatElement("chat-text")?.focus();
}
function chatClose() {
  const panel = chatElement("chat-panel");
  const toggle = chatElement("chat-toggle");
  if (!panel || !toggle) return;
  panel.hidden = true;
  toggle.setAttribute("aria-expanded", "false");
  toggle.focus();
}
function chatUpdateMapsLink() {
  const address = chatElement("shipping-address")?.value.trim() || "";
  const link = chatElement("shipping-maps-link");
  if (!link) return;
  const destination = address || "Guaratingueta, SP";
  link.href = `https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent("Guaratingueta, SP")}&destination=${encodeURIComponent(destination)}&travelmode=driving`;
  link.setAttribute(
    "aria-label",
    address
      ? "Abrir rota de Guaratinguetá ao endereço informado no Google Maps"
      : "Abrir Google Maps",
  );
}
function chatCalculateShipping(event) {
  event.preventDefault();
  const form = event.currentTarget;
  if (!form.reportValidity()) return;
  const address = form.elements.address.value.trim();
  const distanceKm = Number(
    String(form.elements.distance.value).replace(",", "."),
  );
  if (!address || !Number.isFinite(distanceKm) || distanceKm <= 0) {
    chatAddMessage(
      "bot",
      "Informe o endereço e uma distância rodoviária válida em quilómetros.",
    );
    return;
  }
  if (distanceKm > 100) {
    freightQuote = null;
    desenharCarrinho();
    chatAddMessage("bot", "Não é possível efetuar essa entrega");
    return;
  }
  const cost = Math.round(distanceKm * 400) / 100;
  freightQuote = { distanceKm, cost };
  desenharCarrinho();
  const subtotal = carrinho.reduce(
    (sum, item) => sum + item.preco * item.qtd,
    0,
  );
  const total = subtotal + cost;
  chatAddMessage(
    "bot",
    `Entrega desde Guaratinguetá: ${distanceKm.toLocaleString("pt-BR")} km × R$ 4,00 = ${dinheiro(cost)}.
Subtotal dos itens: ${dinheiro(subtotal)}
Total da compra com frete: ${dinheiro(total)}. O frete foi incluído no total do carrinho.`,
  );
  chatScrollToBottom();
}

function chatInit() {
  const toggle = chatElement("chat-toggle");
  const close = chatElement("chat-close");
  const fileInput = chatElement("chat-file");
  const selectImage = chatElement("chat-select-image");
  const removeImage = chatElement("chat-remove-image");
  const form = chatElement("chat-form");
  const shippingForm = chatElement("chat-shipping-form");
  const shippingAddress = chatElement("shipping-address");
  shippingAddress?.addEventListener("input", chatUpdateMapsLink);
  shippingForm?.addEventListener("submit", chatCalculateShipping);
  toggle?.addEventListener("click", chatOpen);
  close?.addEventListener("click", chatClose);
  selectImage?.addEventListener("click", () => fileInput?.click());
  removeImage?.addEventListener("click", () => chatClearPreview(true));
  fileInput?.addEventListener("change", async () => {
    const file = fileInput.files && fileInput.files[0];
    if (!file) return;
    if (!["image/jpeg", "image/png", "image/webp"].includes(file.type)) {
      chatClearPreview(true);
      chatAddMessage(
        "bot",
        "Formato não suportado. Selecione uma imagem JPG, PNG ou WebP.",
      );
      return;
    }
    if (file.size > CHAT_MAX_IMAGE_BYTES) {
      chatClearPreview(true);
      chatAddMessage("bot", "A imagem é muito grande. O limite é 5 MB.");
      return;
    }
    chatClearPreview(true);
    chatSelectedFile = file;
    chatPreviewUrl = URL.createObjectURL(file);
    const image = chatElement("chat-preview-image");
    const name = chatElement("chat-preview-name");
    const preview = chatElement("chat-preview");
    if (image) image.src = chatPreviewUrl;
    if (name) name.textContent = file.name;
    if (preview) preview.hidden = false;
    try {
      await image.decode();
    } catch {
      chatClearPreview(true);
      chatAddMessage(
        "bot",
        "A imagem parece inválida ou está danificada. Escolha outro arquivo.",
      );
    }
  });
  form?.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (chatAnalyzing) return;
    const textInput = chatElement("chat-text");
    const text = textInput?.value.trim() || "";
    const file = chatSelectedFile;
    const url = chatPreviewUrl;
    if (!text && !file) return;
    if (text) {
      chatAddMessage("user", text);
      textInput.value = "";
      chatAnswerText(text);
    }
    if (file && url) {
      chatAddMessage(
        "user",
        "Vou enviar esta imagem para identificação.",
        file.name,
      );
      chatClearPreview(false);
      try {
        await chatAnalyzeImage(file, url);
      } catch (error) {
        chatAddMessage(
          "bot",
          error instanceof Error
            ? error.message
            : "Não foi possível analisar a imagem. Confira o modelo e tente novamente.",
        );
      } finally {
        chatSetStatus("");
        chatSetBusy(false);
      }
    }
    textInput?.focus();
  });
  chatAddMessage(
    "bot",
    "Olá! Bem-vindo à LEVELUP! Posso ajudar você a encontrar seu próximo jogo, identificar uma capa ou calcular o frete. Para frete, informe a distância da rota de carro desde Guaratinguetá.",
  );
}

document.addEventListener("click", (event) => {
  if (event.target.closest('[data-acao="abrir-assistente"]')) chatOpen();
});
document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && !chatElement("chat-panel")?.hidden) chatClose();
});
chatInit();
